-- GENERATED by apps/api/scripts/v3-scaffolds.mjs, then reviewed. Explicit SQL: every policy is spelled out.
-- SECURITY-REVIEW-REQUIRED: scaffold tables for all v1 modules (Sprints 1-6). Each table has
-- tenant_id, unique (tenant_id, id), composite same-tenant FKs, an index leading with tenant_id,
-- ENABLE + FORCE RLS, select/insert/update/delete policies and explicit grants to trackdesk_app.
-- Write policies also check the role permission matrix (app_has_permission) — RLS mirrors Spring Security.

-- =============================== Sprint 1 ===============================

create table site (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenant (id),
  customer_id uuid not null,
  name text not null,
  address_line1 text, address_line2 text, city text, postcode text,
  location geography(Point, 4326),
  access_notes text,
  status text not null default 'active' check (status in ('active', 'archived')),
  version bigint not null default 0,
  foreign key (tenant_id, customer_id) references customer (tenant_id, id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, id)
);
create index site_ix1 on site (tenant_id, customer_id);
create index site_ix2 on site using gist (location);
alter table site enable row level security;
alter table site force row level security;
create policy site_select on site for select
  using (tenant_id = app_current_tenant() and (app_current_role() is distinct from 'customer' or customer_id = app_current_customer()));
create policy site_insert on site for insert
  with check (tenant_id = app_current_tenant() and (app_has_permission('sites:write')));
create policy site_update on site for update
  using (tenant_id = app_current_tenant() and (app_current_role() is distinct from 'customer' or customer_id = app_current_customer()) and (app_has_permission('sites:write')))
  with check (tenant_id = app_current_tenant());
grant select, insert, update on site to trackdesk_app;

create table asset (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenant (id),
  site_id uuid not null,
  asset_type text not null check (asset_type in ('fire_alarm_panel','smoke_detector','heat_detector','call_point','sounder','beacon','emergency_light','exit_sign','central_battery','other')),
  standard text not null check (standard in ('BS5839','BS5266','OTHER')),
  manufacturer text, model text, serial_number text,
  location_description text,
  location geography(Point, 4326),
  installed_on date,
  status text not null default 'active' check (status in ('active', 'decommissioned')),
  version bigint not null default 0,
  foreign key (tenant_id, site_id) references site (tenant_id, id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, id)
);
create index asset_ix1 on asset (tenant_id, site_id);
alter table asset enable row level security;
alter table asset force row level security;
create policy asset_select on asset for select
  using (tenant_id = app_current_tenant() and (app_current_role() is distinct from 'customer' or exists (select 1 from site s where s.tenant_id = asset.tenant_id and s.id = asset.site_id and s.customer_id = app_current_customer())));
create policy asset_insert on asset for insert
  with check (tenant_id = app_current_tenant() and (app_has_permission('assets:write')));
create policy asset_update on asset for update
  using (tenant_id = app_current_tenant() and (app_current_role() is distinct from 'customer' or exists (select 1 from site s where s.tenant_id = asset.tenant_id and s.id = asset.site_id and s.customer_id = app_current_customer())) and (app_has_permission('assets:write')))
  with check (tenant_id = app_current_tenant());
grant select, insert, update on asset to trackdesk_app;

