create table job (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references tenant (id),
  customer_id uuid not null,
  site_id uuid not null,
  work_order_id uuid,
  maintenance_schedule_id uuid,
  reference text not null,
  job_type text not null check (job_type in ('service','repair','install','inspection','callout')),
  standard text check (standard in ('BS5839','BS5266','OTHER')),
  status text not null default 'draft' check (status in ('draft','scheduled','dispatched','en_route','on_site','completed','verified','invoiced','cancelled','overdue')),
  priority text not null default 'normal' check (priority in ('low','normal','high','emergency')),
  title text,
  scheduled_start timestamptz,
  scheduled_end timestamptz,
  assigned_user_id uuid,
  sla_due_at timestamptz,
  completed_at timestamptz,
  verified_at timestamptz,
  client_id uuid,
  version bigint not null default 0,
  unique (tenant_id, reference),
  unique (tenant_id, client_id),
  unique (tenant_id, maintenance_schedule_id, sla_due_at),
  check (scheduled_end is null or scheduled_start is null or scheduled_end > scheduled_start),
  foreign key (tenant_id, customer_id) references customer (tenant_id, id),
  foreign key (tenant_id, site_id) references site (tenant_id, id),
  foreign key (tenant_id, work_order_id) references work_order (tenant_id, id),
  foreign key (tenant_id, maintenance_schedule_id) references maintenance_schedule (tenant_id, id),
  foreign key (tenant_id, assigned_user_id) references app_user (tenant_id, id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, id)
);
create index job_ix1 on job (tenant_id, status);
create index job_ix2 on job (tenant_id, assigned_user_id, scheduled_start);
create index job_ix3 on job (tenant_id, customer_id);
alter table job enable row level security;
alter table job force row level security;
create policy job_select on job for select
  using (tenant_id = app_current_tenant() and (app_current_role() is distinct from 'customer' or customer_id = app_current_customer()) and (app_current_role() is distinct from 'field_worker' or assigned_user_id = app_current_user()));
create policy job_insert on job for insert
  with check (tenant_id = app_current_tenant() and (app_has_permission('jobs:write') or app_has_permission('jobs:transition') or app_has_permission('dispatch:assign')));
create policy job_update on job for update
  using (tenant_id = app_current_tenant() and (app_current_role() is distinct from 'customer' or customer_id = app_current_customer()) and (app_current_role() is distinct from 'field_worker' or assigned_user_id = app_current_user()) and (app_has_permission('jobs:write') or app_has_permission('jobs:transition') or app_has_permission('dispatch:assign')))
  with check (tenant_id = app_current_tenant());
grant select, insert, update on job to trackdesk_app;

